  bulkSaveMarks: async (list) => {
    apiFetch('/results/bulk', { method: 'POST', body: JSON.stringify(list) }).catch(() => {});
    const results = localGet(STORAGE_KEYS.FAC_RESULTS, SEED_RESULTS);
    const touchedSids = new Set();

    list.forEach(item => {
      const m = item.marksObtained;
      const isAbsent = item.isAbsent || false;
      const finalGrade = isAbsent ? 'AB' : (m >= 90 ? 'O' : m >= 80 ? 'A+' : m >= 70 ? 'A' : m >= 60 ? 'B+' : m >= 50 ? 'B' : m >= 40 ? 'C' : 'F');
      const finalGradePoint = isAbsent ? 0.0 : (m >= 90 ? 10.0 : m >= 80 ? 9.0 : m >= 70 ? 8.0 : m >= 60 ? 7.0 : m >= 50 ? 6.0 : m >= 40 ? 5.0 : 0.0);

      const idx = results.findIndex(r => r.studentId === item.studentId && r.subjectId === item.subjectId);
      if (idx >= 0) {
        results[idx] = { ...results[idx], ...item, finalGrade, finalGradePoint, isFinalized: true };
      } else {
        results.push({
          id: 'res_' + Date.now() + '_' + Math.floor(Math.random()*1000),
          ...item,
          finalGrade,
          finalGradePoint,
          isFinalized: true
        });
      }
      touchedSids.add(item.studentId);
    });

    localSet(STORAGE_KEYS.FAC_RESULTS, results);
    touchedSids.forEach(sid => syncStudentMarksToShared(sid));
    return { ok: true, data: { count: list.length } };
  },

